// Prepare Apify Google Maps Scraper input
// Process each search query into an Apify-compatible format
const queries = $input.all().map(item => item.json);

// Filter enabled queries
const enabledQueries = queries.filter(q => 
  q.enabled === 'TRUE' || q.enabled === true || q.enabled === 'true'
);

if (enabledQueries.length === 0) {
  throw new Error('No enabled search queries found in SEARCH_QUERIES sheet');
}

// Build search terms for Google Maps
const searchTerms = enabledQueries.map(q => {
  const region = q.region ? `, ${q.region}` : '';
  return `${q.query}${region}, Switzerland`;
});

return [{
  json: {
    searchTerms: searchTerms,
    queries: enabledQueries,
    totalQueries: enabledQueries.length
  }
}];

// Normalize Apify Google Maps results into our HOTELS schema
const results = $input.all();
const hotels = [];
const rejected = [];
const now = new Date().toISOString();

function normalizeDomain(url) {
  if (!url) return null;
  try {
    let hostname = new URL(url).hostname.toLowerCase();
    hostname = hostname.replace(/^www\./, '');
    return hostname;
  } catch {
    return null;
  }
}

function normalizeHotelName(name) {
  if (!name) return null;
  return name
    .toLowerCase()
    .replace(/[^a-z0-9äöüàâéèêëïîôùûüÿç\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function generateId() {
  const ts = Date.now().toString(36);
  const rand = Math.random().toString(36).slice(2, 8);
  return `htl-${ts}-${rand}`;
}

// Irrelevant categories to reject
const rejectPatterns = [
  'apartment', 'ferienwohnung', 'holiday home', 'vacation rental',
  'camping', 'campingplatz', 'hostel', 'jugendherberge',
  'bed and breakfast', 'b&b', 'airbnb', 'privatzimmer',
  'immobilien', 'real estate', 'travel agency', 'reisebüro'
];

for (const result of results) {
  const item = result.json;

  // Skip if not in Switzerland
  const address = (item.address || '').toLowerCase();
  const country = (item.countryCode || '').toUpperCase();
  if (country && country !== 'CH') {
    continue;
  }
  // Additional CH check from address
  if (!country && !address.includes('schweiz') && !address.includes('switzerland') && !address.includes('suisse') && !address.includes(', ch')) {
    // Try to infer from location
    const loc = (item.location || item.city || '').toLowerCase();
    if (!loc) continue;
  }

  const name = item.title || item.name || '';
  const normalizedName = normalizeHotelName(name);

  // Check for irrelevant listings
  const category = (item.categoryName || item.category || '').toLowerCase();
  const isIrrelevant = rejectPatterns.some(p => 
    category.includes(p) || name.toLowerCase().includes(p)
  );

  if (isIrrelevant) {
    rejected.push({ name, reason: 'Irrelevant category: ' + category });
    continue;
  }

  // Extract website
  const website = item.website || item.url || null;
  const normalizedDomain = normalizeDomain(website);

  // Determine hotel type
  let hotelType = 'HOTEL';
  const nameLower = name.toLowerCase();
  if (nameLower.includes('resort')) hotelType = 'RESORT';
  else if (nameLower.includes('berghotel') || nameLower.includes('berghaus')) hotelType = 'BERGHOTEL';
  else if (nameLower.includes('gasthof') || nameLower.includes('gasthaus')) hotelType = 'GASTHOF';
  else if (nameLower.includes('wellness')) hotelType = 'RESORT';

  // Extract location info
  const town = item.city || item.neighborhood || '';
  const canton = item.state || '';

  hotels.push({
    hotel_id: generateId(),
    hotel_name: name,
    normalized_name: normalizedName,
    town: town,
    canton: canton,
    country: 'CH',
    language_region: 'DE',
    hotel_type: hotelType,
    stars: item.totalScore || '',
    website: website || '',
    normalized_domain: normalizedDomain || '',
    source_url: item.url || item.searchPageUrl || '',
    career_url: '',
    contact_url: '',
    accommodation: 'UNKNOWN',
    meals: 'UNKNOWN',
    active_vacancy: 'UNKNOWN',
    status: website ? 'DISCOVERED' : 'SCRAPE_PENDING',
    priority: 'MEDIUM',
    manual_review: website ? 'FALSE' : 'TRUE',
    created_at: now,
    updated_at: now,
    last_error: ''
  });
}

return [{
  json: {
    hotels: hotels,
    rejected: rejected,
    total_found: results.length,
    total_valid: hotels.length,
    total_rejected: rejected.length
  }
}];

// Deduplicate new hotels against existing ones
const normalizedData = $('Normalize Results').first().json;
const existingItems = $('Read Existing Hotels').all();

// Build sets of existing identifiers
const existingDomains = new Set();
const existingNames = new Set();

for (const item of existingItems) {
  const row = item.json;
  if (row.normalized_domain) {
    existingDomains.add(row.normalized_domain.toLowerCase());
  }
  const nameKey = `${(row.normalized_name || '').toLowerCase()}|${(row.town || '').toLowerCase()}`;
  if (row.normalized_name) {
    existingNames.add(nameKey);
  }
}

// Also deduplicate within the new batch
const seenDomains = new Set();
const seenNames = new Set();
const newHotels = [];
const duplicates = [];

for (const hotel of normalizedData.hotels) {
  const domain = (hotel.normalized_domain || '').toLowerCase();
  const nameKey = `${(hotel.normalized_name || '').toLowerCase()}|${(hotel.town || '').toLowerCase()}`;

  // Check against existing
  if (domain && existingDomains.has(domain)) {
    duplicates.push({ name: hotel.hotel_name, reason: 'Domain exists: ' + domain });
    continue;
  }
  if (existingNames.has(nameKey)) {
    duplicates.push({ name: hotel.hotel_name, reason: 'Name+town exists' });
    continue;
  }

  // Check within batch
  if (domain && seenDomains.has(domain)) {
    duplicates.push({ name: hotel.hotel_name, reason: 'Duplicate in batch: ' + domain });
    continue;
  }
  if (seenNames.has(nameKey)) {
    duplicates.push({ name: hotel.hotel_name, reason: 'Name duplicate in batch' });
    continue;
  }

  if (domain) seenDomains.add(domain);
  seenNames.add(nameKey);
  newHotels.push(hotel);
}

return [{
  json: {
    new_hotels: newHotels,
    duplicates: duplicates,
    total_new: newHotels.length,
    total_duplicates: duplicates.length,
    total_existing: existingItems.length
  }
}];

// Split new hotels into individual items for Google Sheets append
const data = $input.first().json;
const hotels = data.new_hotels;

return hotels.map(hotel => ({ json: hotel }));

// Create discovery event for logging
const dedupeData = $('Deduplicate Hotels').first().json;
const now = new Date().toISOString();

const event = {
  event_id: now.replace(/[^0-9]/g, '').slice(0, 17) + '-' + Math.random().toString(36).slice(2, 8),
  timestamp: now,
  workflow: 'WF-01 Hotel Discovery',
  entity_type: 'BATCH',
  entity_id: 'discovery-' + now.slice(0, 10),
  event_type: 'DISCOVERY_COMPLETE',
  details_json: JSON.stringify({
    total_new: dedupeData.total_new,
    total_duplicates: dedupeData.total_duplicates,
    total_existing_before: dedupeData.total_existing,
    duplicates_list: dedupeData.duplicates.slice(0, 20)
  })
};

return [{ json: event }];

// Log summary when no new hotels found
const data = $input.first().json;
console.log(`Discovery complete: ${data.total_duplicates} duplicates found, 0 new hotels.`);
return [{ json: { message: 'No new hotels to insert', duplicates: data.total_duplicates } }];
